    class FfiConverterTypeWsConnection : FfiConverter<WsConnection, ulong>
    {
        public ConcurrentHandleMap<WsConnection> handleMap = new ConcurrentHandleMap<WsConnection>();

        public static FfiConverterTypeWsConnection INSTANCE = new FfiConverterTypeWsConnection();

        static FfiConverterTypeWsConnection()
        {
            UniffiCallbackInterfaceWsConnection.Register();
        }

        public override ulong Lower(WsConnection value)
        {
            if (value is WsConnectionImpl rustObj)
            {
                // Rust-implemented object. Clone the handle and return it.
                return rustObj.CallWithPointer(thisPtr => thisPtr);
            }
            else
            {
                // C# object, generate a new handle map entry and return it.
                return handleMap.Insert(value);
            }
        }

        public override WsConnection Lift(ulong value)
        {
            if ((value & 1UL) == 0UL)
            {
                // Rust-generated handle, construct a new wrapper.
                return new WsConnectionImpl(value);
            }
            else
            {
                // C#-generated handle, retrieve and remove from the handle map.
                if (handleMap.Remove(value, out var obj))
                {
                    return obj;
                }
                else
                {
                    throw new InternalException($"No callback in handlemap '{value}'");
                }
            }
        }

        public override WsConnection Read(BigEndianStream stream)
        {
            return Lift(stream.ReadULong());
        }

        public override int AllocationSize(WsConnection value)
        {
            return 8;
        }

        public override void Write(WsConnection value, BigEndianStream stream)
        {
            stream.WriteULong(Lower(value));
        }
    }

