    /// <summary>
    /// The HTTP method for an [`HttpClient::request`].
    /// </summary>
    public enum HttpMethod : int
    {
        Get,
        Post,
    }

    class FfiConverterTypeHttpMethod : FfiConverterRustBuffer<HttpMethod>
    {
        public static FfiConverterTypeHttpMethod INSTANCE = new FfiConverterTypeHttpMethod();

        public override HttpMethod Read(BigEndianStream stream)
        {
            var value = stream.ReadInt();
            switch (value)
            {
                case 1:
                    return HttpMethod.Get;
                case 2:
                    return HttpMethod.Post;
                default:
                    throw new InternalException(
                        String.Format(
                            "invalid enum value '{0}' in FfiConverterTypeHttpMethod.Read()",
                            value
                        )
                    );
            }
        }

        public override int AllocationSize(HttpMethod value)
        {
            return 4;
        }

        public override void Write(HttpMethod value, BigEndianStream stream)
        {
            switch (value)
            {
                case HttpMethod.Get:
                    stream.WriteInt(1);
                    break;
                case HttpMethod.Post:
                    stream.WriteInt(2);
                    break;
                default:
                    throw new InternalException(
                        String.Format(
                            "invalid enum value '{0}' in FfiConverterTypeHttpMethod.Write()",
                            value
                        )
                    );
            }
        }
    }

