            {
                this.@status = @status;
            }
        }

        public class Closed : TransportException
        {
            public Closed()
                : base() { }
        }

        public class Other : TransportException
        {
            // Members
            public string @v1;

            // Constructor
            public Other(string @v1)
                : base("@v1" + "=" + @v1)
            {
