                    return new TransportException.Http(FfiConverterUInt16.INSTANCE.Read(stream));
                case 4:
                    return new TransportException.Closed();
                case 5:
                    return new TransportException.Other(FfiConverterString.INSTANCE.Read(stream));
                default:
                    throw new InternalException(
                        String.Format(
                            "invalid error value '{0}' in FfiConverterTypeTransportError.Read()",
                            value
                        )
                    );
            }
        }

        public override int AllocationSize(TransportException value)
        {
            switch (value)
            {
                case TransportException.Timeout variant_value:
                    return 4;

                case TransportException.Connection variant_value:
                    return 4 + FfiConverterString.INSTANCE.AllocationSize(variant_value.@v1);

                case TransportException.Http variant_value:
                    return 4 + FfiConverterUInt16.INSTANCE.AllocationSize(variant_value.@status);

                case TransportException.Closed variant_value:
                    return 4;

                case TransportException.Other variant_value:
                    return 4 + FfiConverterString.INSTANCE.AllocationSize(variant_value.@v1);
                default:
                    throw new InternalException(
                        String.Format(
                            "invalid error value '{0}' in FfiConverterTypeTransportError.AllocationSize()",
                            value
                        )
                    );
            }
        }

        public override void Write(TransportException value, BigEndianStream stream)
        {
            switch (value)
            {
                case TransportException.Timeout variant_value:
                    stream.WriteInt(1);
                    break;
                case TransportException.Connection variant_value:
                    stream.WriteInt(2);
                    FfiConverterString.INSTANCE.Write(variant_value.@v1, stream);
                    break;
                case TransportException.Http variant_value:
                    stream.WriteInt(3);
                    FfiConverterUInt16.INSTANCE.Write(variant_value.@status, stream);
                    break;
                case TransportException.Closed variant_value:
                    stream.WriteInt(4);
                    break;
                case TransportException.Other variant_value:
                    stream.WriteInt(5);
                    FfiConverterString.INSTANCE.Write(variant_value.@v1, stream);
                    break;
                default:
                    throw new InternalException(
                        String.Format(
                            "invalid error value '{0}' in FfiConverterTypeTransportError.Write()",
                            value
                        )
                    );
            }
        }
    }

    class FfiConverterOptionalByteArray : FfiConverterRustBuffer<byte[]?>
    {
        public static FfiConverterOptionalByteArray INSTANCE = new FfiConverterOptionalByteArray();

        public override byte[]? Read(BigEndianStream stream)
        {
            if (stream.ReadByte() == 0)
            {
                return null;
            }
            return FfiConverterByteArray.INSTANCE.Read(stream);
        }

        public override int AllocationSize(byte[]? value)
        {
            if (value == null)
            {
                return 1;
            }
            else
            {
                return 1 + FfiConverterByteArray.INSTANCE.AllocationSize((byte[])value);
            }
        }

        public override void Write(byte[]? value, BigEndianStream stream)
        {
            if (value == null)
            {
                stream.WriteByte(0);
            }
            else
            {
                stream.WriteByte(1);
                FfiConverterByteArray.INSTANCE.Write((byte[])value, stream);
            }
        }
    }

    class FfiConverterSequenceTypeHeader : FfiConverterRustBuffer<Header[]>
    {
        public static FfiConverterSequenceTypeHeader INSTANCE = new FfiConverterSequenceTypeHeader();

        public override Header[] Read(BigEndianStream stream)
        {
            var length = stream.ReadInt();
            if (length == 0)
            {
                return System.Array.Empty<Header>();
            }

            var result = new Header[length];
            for (int i = 0; i < length; i++)
            {
                result[i] = FfiConverterTypeHeader.INSTANCE.Read(stream);
            }
            return result;
        }

        public override int AllocationSize(Header[] value)
        {
            var sizeForLength = 4;

            // details/1-empty-list-as-default-method-parameter.md
            if (value == null)
            {
                return sizeForLength;
            }

            var sizeForItems = value.Sum(item => FfiConverterTypeHeader.INSTANCE.AllocationSize(item));
            return sizeForLength + sizeForItems;
        }

        public override void Write(Header[] value, BigEndianStream stream)
        {
            // details/1-empty-list-as-default-method-parameter.md
            if (value == null)
            {
                stream.WriteInt(0);
                return;
            }

            stream.WriteInt(value.Length);
            value.ForEach(item => FfiConverterTypeHeader.INSTANCE.Write(item, stream));
        }
    }

    [UnmanagedFunctionPointer(CallingConvention.Cdecl)]
    delegate void UniFfiFutureCallback(ulong continuationHandle, byte pollResult);

    internal sealed class UniffiForeignFutureHandle : System.IDisposable
    {
        internal CancellationTokenSource Cts { get; } = new CancellationTokenSource();
#if NET9_0_OR_GREATER
        private readonly Lock _lock = new Lock();
#else
        private readonly object _lock = new object();
#endif

        internal void MarkDropped()
        {
            lock (_lock)
            {
                if (!_callbackInvoked)
                {
                    Cts.Cancel();
                }
            }
        }

        private bool _callbackInvoked = false;

        internal void InvokeCallbackOnce(Action invoke)
        {
            bool shouldInvoke;
            lock (_lock)
            {
                shouldInvoke = !_callbackInvoked;
                if (shouldInvoke)
                    _callbackInvoked = true;
            }
            if (shouldInvoke)
                invoke();
        }

        // Dispose() is called exactly once — from the worker's finally (Task.Run path) or from the
        // synchronous early-return path — always after InvokeCallbackOnce has set _callbackInvoked = true.
        public void Dispose()
        {
            Cts.Dispose();
        }
    }

    internal static class _UniFFIAsync
    {
        internal const byte UNIFFI_RUST_FUTURE_POLL_READY = 0;

        // internal const byte UNIFFI_RUST_FUTURE_POLL_MAYBE_READY = 1;

        internal static ConcurrentHandleMap<TaskCompletionSource<byte>> _async_handle_map =
            new ConcurrentHandleMap<TaskCompletionSource<byte>>();
        public static ConcurrentHandleMap<UniffiForeignFutureHandle> _foreign_futures_map =
            new ConcurrentHandleMap<UniffiForeignFutureHandle>();

        // FFI type for Rust future continuations
        internal class UniffiRustFutureContinuationCallback
        {
            public static UniFfiFutureCallback callback = Callback;

            public static void Callback(ulong continuationHandle, byte pollResult)
            {
                if (_async_handle_map.Remove(continuationHandle, out TaskCompletionSource<byte>? task))
                {
                    task.SetResult(pollResult);
                }
                // else: continuation already completed (e.g. waker called more than once), ignore
            }
        }

        public class UniffiForeignFutureDroppedCallbackImpl
        {
            public static _UniFFILib.UniffiForeignFutureDroppedCallback callback = Callback;

            public static void Callback(ulong handle)
            {
                if (
                    _foreign_futures_map.Remove(handle, out UniffiForeignFutureHandle? futureHandle)
                    && futureHandle is not null
                )
                {
                    futureHandle.MarkDropped();
                }
            }
        }

        public delegate F CompleteFuncDelegate<F>(ulong handle, ref UniffiRustCallStatus status);

        public delegate void CompleteActionDelegate(ulong handle, ref UniffiRustCallStatus status);

        private static async Task PollFuture(ulong rustFuture, Action<ulong, IntPtr, ulong> pollFunc)
        {
            byte pollResult;
            do
            {
                var tcs = new TaskCompletionSource<byte>(
                    TaskCreationOptions.RunContinuationsAsynchronously
                );
                IntPtr callback = Marshal.GetFunctionPointerForDelegate(
                    UniffiRustFutureContinuationCallback.callback
                );
                ulong mapEntry = _async_handle_map.Insert(tcs);
                pollFunc(rustFuture, callback, mapEntry);
                pollResult = await tcs.Task;
            } while (pollResult != UNIFFI_RUST_FUTURE_POLL_READY);
        }

        public static async Task<T> UniffiRustCallAsync<T, F, E>(
            ulong rustFuture,
            Action<ulong, IntPtr, ulong> pollFunc,
            CompleteFuncDelegate<F> completeFunc,
            Action<ulong> freeFunc,
            Func<F, T> liftFunc,
            CallStatusErrorHandler<E> errorHandler
        )
            where E : System.Exception
        {
            try
            {
                await PollFuture(rustFuture, pollFunc);
                var result = _UniffiHelpers.RustCallWithError(
                    errorHandler,
                    (ref UniffiRustCallStatus status) => completeFunc(rustFuture, ref status)
                );
                return liftFunc(result);
            }
            finally
            {
                freeFunc(rustFuture);
            }
        }

        public static async Task UniffiRustCallAsync<E>(
            ulong rustFuture,
            Action<ulong, IntPtr, ulong> pollFunc,
            CompleteActionDelegate completeFunc,
            Action<ulong> freeFunc,
            CallStatusErrorHandler<E> errorHandler
        )
            where E : System.Exception
        {
            try
            {
                await PollFuture(rustFuture, pollFunc);
                _UniffiHelpers.RustCallWithError(
                    errorHandler,
                    (ref UniffiRustCallStatus status) => completeFunc(rustFuture, ref status)
                );
            }
            finally
            {
                freeFunc(rustFuture);
            }
        }
    }
